:root {
  --bg: #0e1726;
  --bg-soft: #16233a;
  --panel: #f7f9fc;
  --ink: #142033;
  --ink-soft: #4a5b74;
  --accent: #2f6df6;
  --accent-deep: #1e4fd0;
  --mint: #22c58b;
  --warn: #e8663c;
  --line: #dde5f0;
  --radius: 16px;
  --font: "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", system-ui, -apple-system, sans-serif;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font);
}

body { min-height: 100vh; }

.app-shell {
  max-width: 1180px;
  margin: 0 auto;
  padding: 22px 20px 28px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.app-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  color: #eaf1ff;
}

.brand { display: flex; align-items: center; gap: 12px; }

.brand-mark {
  width: 42px;
  height: 42px;
  border-radius: 12px;
  background: linear-gradient(135deg, var(--accent), #5b9bff);
  color: #fff;
  font-size: 20px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
}

.brand-text h1 { margin: 0; font-size: 18px; letter-spacing: .5px; }
.brand-text p { margin: 2px 0 0; font-size: 12px; color: #9fb3d1; }

.audience-tag {
  font-size: 12px;
  color: #cfe0ff;
  border: 1px solid rgba(120, 160, 230, .45);
  padding: 6px 12px;
  border-radius: 999px;
  white-space: nowrap;
}

.deck-viewport {
  position: relative;
  background: var(--bg-soft);
  border-radius: 22px;
  padding: 18px;
  box-shadow: 0 20px 50px rgba(0, 0, 0, .35);
}

.deck-stage {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  overflow: hidden;
  border-radius: 14px;
}

.slide {
  position: absolute;
  inset: 0;
  background: var(--panel);
  border-radius: 14px;
  padding: 30px 36px 52px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  overflow: hidden;
  color: var(--ink);
}

.slide[hidden] { display: none; }

.eyebrow {
  margin: 0 0 8px;
  font-size: 12px;
  letter-spacing: 2px;
  font-weight: 700;
  color: var(--accent);
  text-transform: uppercase;
}

/* 封面 */
.slide-cover { background: linear-gradient(150deg, #101d33 0%, #17305a 100%); color: #eef4ff; }
.cover-grid { display: grid; grid-template-columns: 1.5fr 1fr; gap: 30px; flex: 1; align-items: center; }
.cover-main .eyebrow { color: #7fb0ff; }
.cover-title { font-size: clamp(26px, 4vw, 44px); line-height: 1.22; margin: 0 0 14px; font-weight: 800; letter-spacing: 1px; }
.cover-sub { margin: 0 0 18px; font-size: 16px; color: #b9cdea; }
.cover-meta { display: flex; flex-wrap: wrap; gap: 10px; }
.meta-chip {
  font-size: 12px;
  padding: 6px 12px;
  border-radius: 999px;
  background: rgba(140, 175, 255, .16);
  color: #d3e2ff;
  border: 1px solid rgba(140, 175, 255, .28);
}
.cover-aside {
  background: rgba(255, 255, 255, .06);
  border: 1px solid rgba(140, 175, 255, .22);
  border-radius: 14px;
  padding: 18px 20px;
}
.aside-label { margin: 0 0 12px; font-size: 13px; color: #9fbce6; letter-spacing: 1px; }
.cover-list { margin: 0; padding: 0; list-style: none; display: flex; flex-direction: column; gap: 12px; }
.cover-list li { display: flex; gap: 10px; font-size: 14px; color: #e6eeff; align-items: baseline; }
.cover-list li span { font-weight: 700; color: #7fb0ff; font-size: 12px; letter-spacing: 1px; }

/* 常规页头 */
.slide-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; }
.slide-title { margin: 0 0 6px; font-size: clamp(20px, 2.6vw, 30px); font-weight: 800; color: var(--ink); }
.slide-lead { margin: 0; font-size: 14px; color: var(--ink-soft); max-width: 60ch; }
.slide-badge {
  flex: 0 0 auto;
  font-size: 12px;
  font-weight: 700;
  padding: 6px 14px;
  border-radius: 999px;
  background: rgba(47, 109, 246, .12);
  color: var(--accent-deep);
}

/* 指标 */
.metric-grid { flex: 1; display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; align-content: start; }
.metric-card {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 18px 16px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  box-shadow: 0 6px 18px rgba(20, 32, 51, .05);
}
.metric-value { margin: 0; font-size: clamp(22px, 2.8vw, 32px); font-weight: 800; color: var(--accent-deep); line-height: 1.1; }
.metric-name { margin: 0; font-size: 14px; font-weight: 700; }
.metric-note { margin: 0; font-size: 12px; color: var(--ink-soft); }
.metric-accent { background: linear-gradient(160deg, #eaf1ff, #ffffff); }
.metric-accent .metric-value { color: var(--mint); }
.meter-line { height: 8px; border-radius: 99px; background: #e6edf9; overflow: hidden; margin-top: 6px; }
.meter-line span { display: block; height: 100%; background: linear-gradient(90deg, var(--accent), #6fa3ff); border-radius: 99px; }

/* 成果列表 */
.result-list { flex: 1; list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 14px; }
.result-item {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  background: #fff;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 16px 18px;
  box-shadow: 0 6px 18px rgba(20, 32, 51, .05);
}
.result-index { font-size: 22px; font-weight: 800; color: #c6d6ee; line-height: 1; }
.result-body { flex: 1; }
.result-body h3 { margin: 0 0 4px; font-size: 16px; color: var(--ink); }
.result-body p { margin: 0; font-size: 13px; color: var(--ink-soft); line-height: 1.55; }
.result-tag {
  flex: 0 0 auto;
  align-self: center;
  font-size: 12px;
  font-weight: 700;
  padding: 5px 12px;
  border-radius: 999px;
  background: rgba(34, 197, 139, .14);
  color: #138a60;
}

/* 表格 */
.table-wrap { flex: 1; display: flex; align-items: flex-start; overflow: auto; }
.compare-table { width: 100%; border-collapse: collapse; background: #fff; border-radius: var(--radius); overflow: hidden; box-shadow: 0 6px 18px rgba(20, 32, 51, .05); font-size: 13.5px; }
.compare-table caption { text-align: left; padding: 0 0 10px; font-size: 12px; color: var(--ink-soft); }
.compare-table th, .compare-table td { padding: 11px 14px; text-align: left; border-bottom: 1px solid var(--line); }
.compare-table thead th { background: #eef3fc; color: var(--accent-deep); font-size: 13px; }
.compare-table tbody th { font-weight: 700; color: var(--ink); background: #fafcff; }
.compare-table tbody tr:last-child th, .compare-table tbody tr:last-child td { border-bottom: none; }
.trend-up { color: #138a60; font-weight: 700; }
.trend-flat { color: #9a6a12; font-weight: 700; }
.foot-note { margin: 0; font-size: 13px; color: var(--ink-soft); font-weight: 600; }

/* 流程 */
.flow-list { flex: 1; list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; align-content: start; }
.flow-step { background: #fff; border: 1px solid var(--line); border-radius: var(--radius); padding: 16px; box-shadow: 0 6px 18px rgba(20, 32, 51, .05); }
.flow-dot { display: inline-flex; align-items: center; justify-content: center; width: 30px; height: 30px; border-radius: 50%; background: var(--accent); color: #fff; font-weight: 800; font-size: 14px; margin-bottom: 10px; }
.flow-step h3 { margin: 0 0 6px; font-size: 15px; }
.flow-step p { margin: 0; font-size: 12.5px; line-height: 1.55; color: var(--ink-soft); }
.flow-bar { height: 4px; border-radius: 99px; background: #e3eaf6; overflow: hidden; }
.flow-bar span { display: block; width: 100%; height: 100%; background: linear-gradient(90deg, var(--accent), var(--mint)); }

/* 成长与不足 */
.split-grid { flex: 1; display: grid; grid-template-columns: 1fr 1fr; gap: 16px; align-content: start; }
.split-card { background: #fff; border: 1px solid var(--line); border-radius: var(--radius); padding: 18px; box-shadow: 0 6px 18px rgba(20, 32, 51, .05); }
.split-title { margin: 0 0 12px; font-size: 15px; }
.split-title.up { color: #138a60; }
.split-title.down { color: var(--warn); }
.dot-list { margin: 0; padding-left: 18px; display: flex; flex-direction: column; gap: 10px; font-size: 13px; line-height: 1.55; color: var(--ink-soft); }
.dot-list.warn { color: #87441f; }

/* 计划 */
.plan-grid { flex: 1; display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; align-content: start; }
.plan-card { background: #fff; border: 1px solid var(--line); border-radius: var(--radius); padding: 18px; display: flex; flex-direction: column; gap: 8px; box-shadow: 0 6px 18px rgba(20, 32, 51, .05); }
.plan-no { margin: 0; font-size: 12px; font-weight: 700; color: var(--accent-deep); letter-spacing: 1px; }
.plan-card h3 { margin: 0; font-size: 16px; }
.plan-card p { margin: 0; font-size: 13px; line-height: 1.55; color: var(--ink-soft); }
.plan-target { margin-top: auto; font-size: 12px; font-weight: 600; color: #138a60; }
.plan-accent { background: linear-gradient(160deg, #eaf1ff, #ffffff); }

/* 结语 */
.slide-end { align-items: center; justify-content: center; text-align: center; background: linear-gradient(150deg, #101d33 0%, #17305a 100%); color: #eef4ff; }
.end-wrap { display: flex; flex-direction: column; align-items: center; gap: 14px; }
.end-title { margin: 0; font-size: clamp(26px, 3.8vw, 42px); font-weight: 800; line-height: 1.25; }
.end-sub { margin: 0; font-size: 15px; color: #b9cdea; }
.end-points { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin-top: 6px; }
.end-points span { font-size: 12px; padding: 6px 14px; border-radius: 999px; background: rgba(140, 175, 255, .16); border: 1px solid rgba(140, 175, 255, .28); color: #d3e2ff; }

/* 页脚 */
.slide-foot {
  position: absolute;
  left: 36px;
  right: 36px;
  bottom: 18px;
  display: flex;
  justify-content: space-between;
  font-size: 11.5px;
  color: var(--ink-soft);
  border-top: 1px solid var(--line);
  padding-top: 8px;
}
.slide-cover .slide-foot, .slide-end .slide-foot { color: #93acd1; border-top-color: rgba(140, 175, 255, .22); }

/* 导航 */
.deck-controls {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  background: var(--bg-soft);
  border-radius: 16px;
  padding: 12px 18px;
}
.nav-btn {
  font-family: inherit;
  font-size: 14px;
  font-weight: 700;
  color: #dbe8ff;
  background: rgba(120, 160, 230, .16);
  border: 1px solid rgba(120, 160, 230, .35);
  border-radius: 10px;
  padding: 9px 18px;
  cursor: pointer;
  transition: background .18s ease, transform .1s ease;
}
.nav-btn:hover:not(:disabled) { background: rgba(120, 160, 230, .3); }
.nav-btn:active:not(:disabled) { transform: translateY(1px); }
.nav-btn:disabled { opacity: .4; cursor: not-allowed; }
.nav-primary { background: var(--accent); border-color: var(--accent); color: #fff; }
.nav-primary:hover:not(:disabled) { background: var(--accent-deep); }
.deck-status { display: flex; flex-direction: column; align-items: center; gap: 8px; flex: 1; max-width: 320px; }
.position { font-size: 14px; font-weight: 700; color: #eaf1ff; letter-spacing: 1px; }
.progress-track { width: 100%; height: 6px; border-radius: 99px; background: rgba(120, 160, 230, .22); overflow: hidden; }
.progress-fill { display: block; height: 100%; width: 12.5%; border-radius: 99px; background: linear-gradient(90deg, var(--accent), #6fa3ff); transition: width .25s ease; }
.keyboard-hint { margin: 0; text-align: center; font-size: 12px; color: #8ba2c4; }

/* 窄屏适配 */
@media (max-width: 860px) {
  .app-shell { padding: 14px 12px 20px; }
  .deck-viewport { padding: 10px; border-radius: 16px; }
  .slide { padding: 18px 18px 40px; gap: 12px; }
  .cover-grid { grid-template-columns: 1fr; gap: 18px; }
  .cover-aside { display: none; }
  .metric-grid { grid-template-columns: repeat(2, 1fr); }
  .flow-list { grid-template-columns: repeat(2, 1fr); }
  .split-grid { grid-template-columns: 1fr; }
  .plan-grid { grid-template-columns: 1fr; }
  .slide-foot { left: 18px; right: 18px; bottom: 12px; }
  .result-item { padding: 12px 14px; gap: 10px; }
  .compare-table th, .compare-table td { padding: 8px 10px; }
  .deck-controls { padding: 10px 12px; gap: 10px; }
  .nav-btn { padding: 8px 12px; font-size: 13px; }
}

@media (max-width: 520px) {
  .brand-text h1 { font-size: 16px; }
  .audience-tag { display: none; }
  .metric-grid { grid-template-columns: 1fr 1fr; gap: 10px; }
  .metric-card { padding: 12px; }
  .slide-title { font-size: 19px; }
  .slide-lead { font-size: 12.5px; }
  .deck-status { max-width: 140px; }
  .keyboard-hint { font-size: 11px; }
}

