(function () {
  'use strict';

  var slides = Array.prototype.slice.call(document.querySelectorAll('[data-deck-slide]'));
  var prevBtn = document.querySelector('[data-deck-prev]');
  var nextBtn = document.querySelector('[data-deck-next]');
  var positionEl = document.querySelector('[data-deck-position]');
  var progressFill = document.getElementById('progressFill');

  var total = slides.length;
  var current = 0;

  function isEditable(el) {
    if (!el || el.nodeType !== 1) return false;
    var tag = el.tagName;
    if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return true;
    if (el.isContentEditable) return true;
    return false;
  }

  function render() {
    if (total === 0) return;
    if (current < 0) current = 0;
    if (current > total - 1) current = total - 1;

    slides.forEach(function (slide, index) {
      var active = index === current;
      slide.hidden = !active;
      if (active) {
        slide.removeAttribute('hidden');
      } else {
        slide.setAttribute('hidden', '');
      }
      slide.setAttribute('aria-hidden', active ? 'false' : 'true');
    });

    if (positionEl) {
      positionEl.textContent = (current + 1) + ' / ' + total;
    }
    if (progressFill) {
      var pct = total <= 1 ? 100 : ((current + 1) / total) * 100;
      progressFill.style.width = pct + '%';
    }
    if (prevBtn) prevBtn.disabled = current === 0;
    if (nextBtn) nextBtn.disabled = current === total - 1;
  }

  function goTo(index) {
    if (index < 0 || index > total - 1) return;
    if (index === current) {
      render();
      return;
    }
    current = index;
    render();
  }

  function next() { goTo(current + 1); }
  function prev() { goTo(current - 1); }

  if (prevBtn) {
    prevBtn.addEventListener('click', function (event) {
      event.preventDefault();
      prev();
    });
  }
  if (nextBtn) {
    nextBtn.addEventListener('click', function (event) {
      event.preventDefault();
      next();
    });
  }

  document.addEventListener('keydown', function (event) {
    if (event.defaultPrevented) return;
    if (event.isComposing || event.keyCode === 229) return;
    if (event.altKey || event.ctrlKey || event.metaKey) return;

    var target = event.target;
    if (isEditable(target)) return;

    var key = event.key;
    if (key === 'ArrowRight' || key === 'Right' || key === 'PageDown') {
      if (current < total - 1) {
        event.preventDefault();
        next();
      }
      return;
    }
    if (key === 'ArrowLeft' || key === 'Left' || key === 'PageUp') {
      if (current > 0) {
        event.preventDefault();
        prev();
      }
      return;
    }
    if (key === 'Home') {
      event.preventDefault();
      goTo(0);
      return;
    }
    if (key === 'End') {
      event.preventDefault();
      goTo(total - 1);
      return;
    }
  });

  render();
})();
